#ifndef CONFIG_H
#define CONFIG_H

#include <algorithm>
#include <initializer_list>
#include <iostream>
#include <list>
#include <map>
#include <memory>
#include <set>
#include <sstream>
#include <string>
#include <unordered_map>
#include <unordered_set>
#include <vector>
#include <yaml-cpp/yaml.h>

namespace ws {
namespace cfg {

template<typename From, typename To>
class VarConverter {
public:
    To operator()(const From& val) const noexcept {
        return static_cast<To>(val);
    }
};

template<typename From>
class VarConverter<From, std::string> {
public:
    std::string operator()(const From& val) const noexcept {
        return std::to_string(val);
    }
};

template<>
class VarConverter<std::string, std::string> {
public:
    std::string operator()(const std::string& val) const noexcept {
        return val;
    }
};

template<typename To>
class VarConverter<std::string, To> {
public:
    To operator()(const std::string& str) const {
        std::istringstream iss(str);
        To result;
        if (!(iss >> result)) {
            throw std::invalid_argument("Conversion failed");
        }
        return result;
    }
};

template<typename T>
class VarConverter<std::string, std::list<T>> {
public:
    std::list<T> operator()(const std::string& str) const {
        std::istringstream iss(str);
        std::list<T> result;
        T item;
        while (iss >> item) {
            result.push_back(item);
        }
        return result;
    }
};

template<typename T>
class VarConverter<std::list<T>, std::string> {
public:
    std::string operator()(const std::list<T>& lst) const noexcept {
        std::ostringstream oss;
        for (auto it = lst.begin(); it != lst.end(); ++it) {
            if (it != lst.begin()) {
                oss << " ";
            }
            oss << *it;
        }
        return oss.str();
    }
};

template<typename T>
class VarConverter<std::string, std::vector<T>> {
public:
    std::vector<T> operator()(const std::string& str) const {
        std::istringstream iss(str);
        std::vector<T> result;
        T item;
        while (iss >> item) {
            result.push_back(item);
        }
        return result;
    }
};

template<typename T>
class VarConverter<std::vector<T>, std::string> {
public:
    std::string operator()(const std::vector<T>& vec) const noexcept {
        std::ostringstream oss;
        for (auto it = vec.begin(); it != vec.end(); ++it) {
            if (it != vec.begin()) {
                oss << " ";
            }
            oss << *it;
        }
        return oss.str();
    }
};

template<typename T>
class VarConverter<std::string, std::set<T>> {
public:
    std::set<T> operator()(const std::string& str) const {
        std::istringstream iss(str);
        std::set<T> result;
        T item;
        while (iss >> item) {
            result.insert(item);
        }
        return result;
    }
};

