template<typename T>
class VarConverter<std::string, std::map<std::string, T>> {
public:
    std::map<std::string, T> operator()(const std::string& str) const {
        std::istringstream iss(str);
        std::map<std::string, T> result;
        std::string key;
        T value;
        while (iss >> key >> value) {
            result[key] = value;
        }
        return result;
    }
};

template<typename T>
class VarConverter<std::map<std::string, T>, std::string> {
public:
    std::string operator()(const std::map<std::string, T>& map) const noexcept {
        std::ostringstream oss;
        for (auto it = map.begin(); it != map.end(); ++it) {
            if (it != map.begin()) {
                oss << " ";
            }
            oss << it->first << " " << it->second;
        }
        return oss.str();
    }
};

