class VarBase {
public:
    using Ptr = std::shared_ptr<VarBase>;

    virtual ~VarBase() noexcept {}

    const std::string& Name() const noexcept { return name_; }
    const std::string& Description() const noexcept { return description_; }
    virtual std::string ToString() const noexcept = 0;
    virtual void FromString(std::string_view str) = 0;

protected:
    VarBase(const std::string& name, const std::string& description)
        : name_(name), description_(description) {}

private:
    std::string name_;
    std::string description_;
};

template<typename T, typename FromStr = VarConverter<std::string, T>, typename ToStr = VarConverter<T, std::string>>
class Var : public VarBase {
public:
    using OnChange = void(*)();

    Var(const std::string& name, const T& default_val, const std::string& description)
        : VarBase(name, description), val_(default_val) {}

    std::string ToString() const noexcept override {
        return ToStr()(val_);
    }

    void FromString(std::string_view str) override {
        T new_val = FromStr()(std::string(str));
        if (new_val != val_) {
            val_ = new_val;
            NotifyListeners();
        }
    }

    const T& GetValue() const noexcept { return val_; }
    void SetValue(const T& val) noexcept {
        if (val != val_) {
            val_ = val;
            NotifyListeners();
        }
    }

    std::string TypeName() const noexcept {
        return typeid(T).name();
    }

    void RemoveListener(const std::uint64_t key) noexcept {
        listeners_.erase(key);
    }

    void AddListener(OnChange listener) noexcept {
        static std::atomic<std::uint64_t> next_key = 0;
        listeners_[next_key++] = listener;
    }

    void ClearListeners() noexcept {
        listeners_.clear();
    }

private:
    mutable std::shared_mutex mtx_;
    T val_;
    std::unordered_map<std::uint64_t, OnChange> listeners_;

    void NotifyListeners() noexcept {
        for (auto& listener : listeners_) {
            listener.second();
        }
    }
};

class Config {
public:
    using Ptr = std::shared_ptr<Config>;

    const std::string& Name() const noexcept { return name_; }

    template<typename T>
    Var<T>::Ptr Lookup(const std::string_view name, const T& default_val, const std::string_view description = "") {
        std::lock_guard<std::shared_mutex> lock(mtx_);
        auto it = vars_.find(name);
        if (it != vars_.end()) {
            return std::dynamic_pointer_cast<Var<T>>(it->second);
        }
        auto var = std::make_shared<Var<T>>(std::string(name), default_val, description);
        vars_[name] = var;
        return var;
    }

    template<typename T>
    Var<T>::Ptr Lookup(const std::string_view name) const {
        std::lock_guard<std::shared_mutex> lock(mtx_);
        auto it = vars_.find(name);
        if (it != vars_.end()) {
            return std::dynamic_pointer_cast<Var<T>>(it->second);
        }
        throw std::invalid_argument("Variable not found");
    }

    VarBase::Ptr LookupBase(std::string_view name) const noexcept {
        std::lock_guard<std::shared_mutex> lock(mtx_);
        auto it = vars_.find(name);
        if (it != vars_.end()) {
            return it->second;
        }
        return nullptr;
    }

    void LoadYaml(const YAML::Node& root) {
        std::lock_guard<std::shared_mutex> lock(mtx_);
        for (auto&& [name, node] : root) {
            auto var = LookupBase(name);
            if (var) {
                var->FromString(node.as<std::string>());
            }
        }
    }

    void Visit(std::function<void(VarBase::Ptr)> visitor) const noexcept {
        std::lock_guard<std::shared_mutex> lock(mtx_);
        for (auto&& [name, var] : vars_) {
            visitor(var);
        }
    }

protected:
    mutable std::shared_mutex mtx_;
    std::string name_;
    std::unordered_map<std::string, VarBase::Ptr> vars_;
};

Config::Ptr RootConfig();

} // namespace cfg
} // namespace ws

#endif // CONFIG_H

